save(412,dict(paragraphs=["Sanghamitra Bhanja writes poetry, short fiction and essays in Odia, alongside her work in teaching and literary scholarship. Associated with Rama Devi Women’s University in Bhubaneswar, she has taught modern prose and poetry and holds postgraduate qualifications in both Odia and Hindi. Her work on life writing includes translating Rama Devi’s autobiography Jeevan Pathe into Hindi as Kshitij Ke Us Paar, with assistance from Bharati Muduli, and compiling a critical volume on Rama Devi.","In ‘ଅନ୍ଧାର ଭୋଗିଚ ?’, darkness becomes a way of asking whether another person has experienced betrayal, neglect and the exhaustion of trust. The recurring question gathers force through bodily images, threatened breath and a landscape of emptiness. Its direct address makes the reader a listener to suffering rather than a distant observer."],sources=[source('Rama Devi Women’s University — faculty profile','https://rdwu.ac.in/profile/ODIA_SANGHAMITRA-BHANJA.pdf','Exact name and Odia department match source poem end matter; qualifications and teaching modern prose/poetry.'),source('Rama Devi Women’s University — translation and life writing',u,'Names Bhanja as translator, Muduli as assistant, and Bhanja as compiler/editor of critical Rama Devi volume; lines 60–63.')],books=[dict(title='Kshitij Ke Us Paar',detail='Hindi translation of Rama Devi’s Jeevan Pathe, with assistance from Bharati Muduli. Centre of Excellence for Translation and Life Writing.',url=u)],identity_match='Captured poet/story writer/essayist plus poem588 end matter naming Odia department head at Rama Devi Women’s University matches official faculty record.',poems_read=[dict(id=588,title='ଅନ୍ଧାର ଭୋଗିଚ ?',coverage='Full original including preserved department end matter.',basis='Repeated question, darkness, breath, betrayal, grief and neglect. Interpretive paragraph describes this poem only.')],limitations=['Faculty PDF is undated and has elapsed-service figures; no claim of a current headship or current service total added.','Publisher Bodhichhaya direct open failed; catalogue index found but publication-date discrepancies left unresolved; no shelf entry added.','Personal suffering or political affiliation not inferred from poetic voice.'],research_leads=[dict(url='https://www.blackeaglebooks.org/product-category/poetry/page/6/?layout=list&per_page=9',finding='Indexed Bodhichhaya author/title; direct product access failed. Not used for narrative.')],next_action='Independent author/editor check of narrative and transliterated book title.'))
